local({
  band <- recode_values(as.numeric(Age_mother), 1 ~ 21.5, 2 ~ 30, 3 ~ 40, 4 ~ 50, 5 ~ 60)
  shift <- recode_values(wave, "T1" ~ 0, "T2" ~ 0.25, "T3" ~ 0.5, "T4" ~ 0.75, "T5" ~ 1)
  carry_within(band, SC, order = as.numeric(sub("T", "", wave))) + shift
})

local({
  share <- ST_wParent / ST
  case_when(
    share == 0 ~ "Never",
    share <= 0.10 ~ "Rarely",
    share <= 0.35 ~ "Sometimes",
    share <= 0.70 ~ "Often",
    share > 0.70 ~ "Always"
  )
})

local({
  items <- paste0("F1_", 1:8)
  x <- sapply(items, function(v) {
    code <- as.numeric(tbl[[v]])
    (5 - if_else(code %in% 1:5, code, NA_real_)) * 25
  })
  n <- rowSums(!is.na(x))
  if_else(n >= length(items) / 2, rowMeans(x, na.rm = TRUE), NA_real_)
})

